#!/bin/bash
# Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# One rule under test: the OpenCode config a sandbox receives keeps the host's
# model/provider/agent choices but none of the host's permission boundaries, and
# the host file is not modified. No credential is staged — the host
# authenticates with an env var, not auth.json.
#
# Drives stage_opencode_config() against a scratch HOME. The upload itself needs
# a live sandbox; staging does not.
#
# Run: tests/test-opencode-config.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
SANDBOX_SH="${REPO_ROOT}/scripts/sandbox.sh"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

HELPERS="${TMP}/helpers.sh"
sed -n '/^stage_opencode_config()/,/^}/p' "$SANDBOX_SH" > "$HELPERS"
grep -q 'stage_opencode_config' "$HELPERS" \
    || { echo "FAIL: could not lift stage_opencode_config out of sandbox.sh" >&2; exit 1; }
# shellcheck disable=SC1090
source "$HELPERS"

fail=0
check() {
    local what="$1" want="$2" got="$3"
    if [[ "$got" != "$want" ]]; then
        echo "FAIL: ${what}: wanted '${want}', got '${got}'" >&2
        fail=1
    fi
}

FAKE_HOME="${TMP}/home"
mkdir -p "${FAKE_HOME}/.config/opencode" "${FAKE_HOME}/.local/share/opencode"
cat > "${FAKE_HOME}/.config/opencode/opencode.json" <<JSON
{
  "model": "provider/model-a",
  "provider": { "vendor": { "options": { "baseURL": "https://provider.example/v1" } } },
  "instructions": ["${FAKE_HOME}/notes.md"],
  "permissions": [{ "action": "*", "resource": "*", "effect": "ask" }],
  "policies": [{ "action": "tool.use", "resource": "shell:env", "effect": "deny" }],
  "plugins": ["some-plugin@1.0.0"]
}
JSON
cp "${FAKE_HOME}/.config/opencode/opencode.json" "${TMP}/host-config-before"

STAGE="${TMP}/stage"
HOME="$FAKE_HOME" XDG_CONFIG_HOME="${FAKE_HOME}/.config" \
    XDG_DATA_HOME="${FAKE_HOME}/.local/share" \
    stage_opencode_config "$STAGE" \
    || { echo "FAIL: staging reported nothing shipped" >&2; fail=1; }

CONFIG="${STAGE}/.config/opencode/opencode.json"
check "model travels" "provider/model-a" "$(jq -r '.model' "$CONFIG")"
check "provider travels" "https://provider.example/v1" \
    "$(jq -r '.provider.vendor.options.baseURL' "$CONFIG")"
# Host home paths are meaningless in the container.
check "host home path rewritten" '/sandbox/notes.md' \
    "$(jq -r '.instructions[0]' "$CONFIG")"
# The three host boundaries are dropped; anything that would re-add them here
# makes the sandbox prompt's "host blocks do not apply" claim false.
check "permissions dropped" "null" "$(jq -r '.permissions // "null"' "$CONFIG")"
check "policies dropped" "null" "$(jq -r '.policies // "null"' "$CONFIG")"
check "plugins dropped" "null" "$(jq -r '.plugins // "null"' "$CONFIG")"

# Staging must not rewrite the host's own file.
cmp -s "$CONFIG" "${FAKE_HOME}/.config/opencode/opencode.json" \
    && { echo "FAIL: staged config is the host file unchanged (jq never ran?)" >&2; fail=1; }
cmp -s "${TMP}/host-config-before" "${FAKE_HOME}/.config/opencode/opencode.json" \
    || { echo "FAIL: staging modified the host's opencode.json" >&2; fail=1; }

# Nothing on the host is not a success — the caller then uploads nothing
# instead of an empty config that would replace a working one.
EMPTY_HOME="${TMP}/empty-home"
mkdir -p "$EMPTY_HOME"
if HOME="$EMPTY_HOME" XDG_CONFIG_HOME="${EMPTY_HOME}/.config" \
    XDG_DATA_HOME="${EMPTY_HOME}/.local/share" \
    stage_opencode_config "${TMP}/empty-stage"; then
    echo "FAIL: staging reported success with nothing to ship" >&2
    fail=1
fi

# A config that cannot be parsed must be an error, not "nothing to ship" —
# otherwise the sandbox silently launches on defaults.
BROKEN_HOME="${TMP}/broken-home"
mkdir -p "${BROKEN_HOME}/.config/opencode"
echo '{ not json' > "${BROKEN_HOME}/.config/opencode/opencode.json"
status=0
HOME="$BROKEN_HOME" XDG_CONFIG_HOME="${BROKEN_HOME}/.config" \
    stage_opencode_config "${TMP}/broken-stage" 2>/dev/null || status=$?
check "unparseable config is a distinct error" "2" "$status"

if [[ $fail -eq 0 ]]; then
    echo "all opencode-config checks passed"
else
    exit 1
fi
